-- isdhoo
update nodes set attributes = coalesce(attributes, '{}'::jsonb) || '{"island_content_source":"legacy_mtg_guide","island_quick_facts":[{"label":"Location","value":"Laamu Atoll, Southern Maldives"},{"label":"Island Type","value":"Inhabited Local Island"},{"label":"Population","value":"Approximately 950 residents"},{"label":"Size","value":"1.0 km long, 0.6 km wide"},{"label":"Distance from Male","value":"245 km"},{"label":"Transfer Options","value":"Domestic flight + speedboat/ferry"},{"label":"Known For","value":"Beautiful beaches, house reef, traditional culture"},{"label":"Best For","value":"Snorkelers, cultural enthusiasts, budget travelers, nature lovers"}],"island_overview":["Located in the pristine waters of Laamu Atoll, Isdhoo Island (also known as Kalaidhoo) offers visitors an authentic glimpse into traditional Maldivian island life. This charming local island combines natural beauty with rich cultural heritage, providing an unforgettable experience away from the crowds.","Isdhoo is distinguished by its stunning white sand beaches, vibrant house reef, and warm community atmosphere. The island has maintained its traditional character while developing sustainable tourism that benefits the local community and preserves the natural environment.","What makes Isdhoo truly special is its perfect balance of tranquility and adventure. Visitors can enjoy world-class snorkeling, experience authentic Maldivian culture, and relax on some of the most beautiful beaches in the southern Maldives, all while staying in budget-friendly accommodations."],"island_sections":[{"heading":"Location & Map","paragraphs":["Isdhoo Island is beautifully positioned in the southern region of Laamu Atoll, approximately 245 kilometers from Male. This strategic location offers the perfect combination of accessibility and seclusion, providing visitors with an authentic island experience.","The island''s location within the atoll provides natural protection while offering easy access to some of the best snorkeling and diving sites in the Maldives. The surrounding waters are known for their clarity, abundant marine life, and healthy coral reefs."]},{"heading":"Isdhoo: Natural Paradise & Marine Sanctuary","paragraphs":["Isdhoo Island is celebrated for its exceptional natural beauty, featuring pristine white sand beaches, crystal-clear turquoise waters, and one of the most accessible and vibrant house reefs in Laamu Atoll. The island offers a perfect tropical paradise for both relaxation and marine exploration."]},{"heading":"Stunning White Sand Beaches","paragraphs":["Isdhoo features some of the most picturesque beaches in Laamu Atoll, with powdery white sand and crystal-clear waters perfect for swimming and relaxation."]},{"heading":"Exceptional House Reef","paragraphs":["The island''s house reef is easily accessible from shore and offers some of the best snorkeling in the atoll with diverse marine life and colorful corals."]},{"heading":"Authentic Island Life","paragraphs":["Experience genuine Maldivian hospitality and traditional island culture in a peaceful setting that has preserved its authentic character."]},{"heading":"Island Hopping Adventures","paragraphs":["Explore nearby uninhabited islands and pristine sandbanks for the ultimate tropical island adventure and desert island experiences."]},{"heading":"Beach Features","paragraphs":["Isdhoo''s coastal attractions include:"]},{"heading":"Marine Life","paragraphs":["The island''s underwater ecosystem features:"]},{"heading":"Activities & Experiences","paragraphs":["Isdhoo offers an outstanding range of activities that showcase the best of Maldivian marine life, culture, and natural beauty. The island''s pristine environment and rich cultural heritage provide endless opportunities for adventure and discovery."]},{"heading":"House Reef Snorkeling","paragraphs":["Explore the spectacular house reef directly from the beach, featuring vibrant corals, tropical fish, and crystal-clear waters with excellent visibility."]},{"heading":"Scuba Diving Excursions","paragraphs":["Discover world-renowned dive sites around Laamu Atoll with experienced dive operators offering courses and guided underwater adventures."]},{"heading":"Pristine Sandbank Tours","paragraphs":["Visit untouched sandbanks and uninhabited islands for picnics, swimming, and the ultimate desert island experience in paradise."]},{"heading":"Traditional Night Fishing","paragraphs":["Join local fishermen for authentic night fishing experiences using traditional hand lines under the magnificent Maldivian starlit sky."]},{"heading":"Cultural Immersion","paragraphs":["Engage with the local community, learn traditional crafts, and experience authentic Maldivian customs, music, and daily life."]},{"heading":"Dolphin Watching","paragraphs":["Experience magical dolphin watching cruises during sunset, often combined with traditional dhoni sailing and photography opportunities."]},{"heading":"People & Community Life","paragraphs":["Isdhoo is home to a vibrant community of approximately 950 residents who have successfully preserved traditional Maldivian culture while embracing sustainable tourism. The island''s population is known for their exceptional hospitality, strong family values, and deep connection to the ocean."]},{"heading":"Island Life","paragraphs":["Daily life on Isdhoo follows the natural rhythms of island living, with the community engaging in fishing, agriculture, and tourism-related activities. The island maintains a peaceful atmosphere where traditional values coexist harmoniously with modern conveniences."]},{"heading":"Cultural Heritage","paragraphs":["Isdhoo preserves rich Maldivian cultural traditions including traditional music, dance, and handicrafts. The community celebrates Islamic festivals with great enthusiasm and maintains traditional practices such as dhoni boat building, traditional fishing methods, and local cuisine preparation."]},{"heading":"Sustainable Tourism","paragraphs":["The island has embraced sustainable tourism practices that benefit the local community while preserving the natural environment. Many families participate in tourism through guesthouses, restaurants, and tour services, creating economic opportunities while maintaining cultural authenticity."]}],"island_faqs":[{"question":"How do I reach Isdhoo Island?","answer":"Seaplane transfers are also available but depend on weather conditions. There''s also a weekly public ferry from Male that takes 14-16 hours."},{"question":"When is the best time to visit Isdhoo?","answer":"The optimal time to visit Isdhoo is during the dry season from December to April when weather conditions are most favorable with minimal rainfall. However, the island can be visited year-round, with the wet season (May-November) offering fewer crowds and more competitive accommodation rates."},{"question":"What accommodation types are available on Isdhoo?","answer":"Isdhoo offers various budget-friendly and mid-range accommodations including traditional family guesthouses and beachfront properties. Most accommodations feature air conditioning, private bathrooms, and meal packages."},{"question":"What activities can I enjoy on Isdhoo?","answer":"Isdhoo offers excellent house reef snorkeling, diving excursions, island hopping tours, cultural experiences, traditional fishing trips, and dolphin watching cruises. The island is particularly renowned for its accessible house reef and authentic cultural experiences with the local community."}],"island_nearby_slugs":["fonadhoo","hithadhoo","gan","maabaidhoo","mundoo","kunahandhoo","dhanbidhoo","maamendhoo","maavah"]}'::jsonb
where node_type = 'location' and slug = 'isdhoo';


-- kaashidhoo
update nodes set attributes = coalesce(attributes, '{}'::jsonb) || '{"island_content_source":"legacy_mtg_guide","island_quick_facts":[{"label":"Location","value":"Kaafu Atoll, North Male Atoll"},{"label":"Island Type","value":"Inhabited Local Island"},{"label":"Population","value":"Approximately 1,800 residents"},{"label":"Size","value":"2.7 km long, 1.2 km wide"},{"label":"Distance from Male","value":"50 km"},{"label":"Transfer Options","value":"Public ferry, speedboat"},{"label":"Known For","value":"Beautiful beaches, authentic culture, agriculture"},{"label":"Best For","value":"Cultural travelers, budget travelers, nature lovers"}],"island_overview":["Located in the Kaafu Atoll approximately 50 kilometers north of Male, Kaashidhoo Island offers visitors an authentic Maldivian experience away from the crowds. This tranquil island maintains its traditional character while providing excellent facilities for tourists seeking cultural immersion in the Maldives.","What makes Kaashidhoo special is its peaceful atmosphere and pristine natural environment. The island features beautiful beaches with powdery white sand and crystal-clear turquoise waters, perfect for relaxation and water activities.","Visitors to Kaashidhoo are drawn by its authentic cultural experiences, excellent marine life, and budget-friendly accommodations. The island''s location provides a peaceful retreat with a distinct local character while still being accessible from Male."],"island_sections":[{"heading":"Location & Map","paragraphs":["Kaashidhoo Island is situated in the northern part of Kaafu Atoll (North Male Atoll), approximately 50 kilometers from Male. This location provides a peaceful retreat while still being accessible from the capital.","The island''s position offers protection from strong currents and provides excellent conditions for swimming and snorkeling. The surrounding waters feature healthy coral reefs and abundant marine life."]},{"heading":"Kaashidhoo: Natural Beauty & Beaches","paragraphs":["Kaashidhoo Island is renowned for its pristine beaches and natural beauty, featuring white sand shores and healthy coral reefs. The island offers visitors a peaceful tropical paradise with excellent swimming and snorkeling opportunities."]},{"heading":"Beautiful White Sand Beaches","paragraphs":["The island features stunning white sand beaches with crystal-clear turquoise waters, offering the perfect setting for relaxation and water activities."]},{"heading":"Excellent Snorkeling","paragraphs":["Explore the vibrant house reef accessible from shore, featuring diverse marine life and coral formations perfect for snorkeling enthusiasts."]},{"heading":"Authentic Island Life","paragraphs":["Experience traditional Maldivian culture and hospitality, with opportunities to interact with friendly locals and learn about their way of life."]},{"heading":"Traditional Fishing","paragraphs":["Witness or participate in traditional fishing methods that have sustained the island community for generations."]},{"heading":"Natural Highlights","paragraphs":["Kaashidhoo''s natural environment offers:"]},{"heading":"Marine Environment","paragraphs":["The island''s marine ecosystem features:"]},{"heading":"Activities & Experiences","paragraphs":["Kaashidhoo offers a variety of activities focused on marine adventures and cultural experiences. The island''s peaceful environment provides excellent opportunities for both relaxation and exploration."]},{"heading":"Snorkeling","paragraphs":["Explore the vibrant house reef directly from shore or join boat excursions to nearby coral gardens and marine sanctuaries."]},{"heading":"Scuba Diving","paragraphs":["Discover underwater wonders at nearby dive sites with professional dive operators offering courses and guided dives."]},{"heading":"Sandbank Visits","paragraphs":["Experience pristine uninhabited sandbanks for picnics, swimming, and the ultimate desert island adventure."]},{"heading":"Traditional Fishing","paragraphs":["Join local fishermen for traditional night fishing experiences using hand lines under the starlit sky."]},{"heading":"Cultural Experiences","paragraphs":["Engage with local community life, learn traditional crafts, and experience authentic Maldivian hospitality."]},{"heading":"Beach Relaxation","paragraphs":["Enjoy the peaceful beaches with powdery white sand and crystal-clear waters perfect for swimming and sunbathing."]},{"heading":"People & Community Life","paragraphs":["Kaashidhoo is home to a friendly community of approximately 1,800 residents who maintain traditional Maldivian lifestyles. The island''s population is known for their hospitality, strong community bonds, and welcoming attitude toward visitors."]},{"heading":"Daily Life","paragraphs":["Life on Kaashidhoo follows traditional Maldivian rhythms, beginning with morning prayers and continuing with fishing, agriculture, and community activities. The island maintains a peaceful atmosphere where traditional values are preserved."]},{"heading":"Culture & Traditions","paragraphs":["Kaashidhoo preserves authentic Maldivian cultural traditions including traditional music, dance, and crafts. The community celebrates Islamic festivals with enthusiasm and maintains traditional practices such as boat building, fishing techniques, and local cuisine preparation."]},{"heading":"Agriculture","paragraphs":["Unlike many Maldivian islands, Kaashidhoo has significant agricultural activity, with coconut palms and other crops cultivated on the island. Visitors can learn about traditional farming methods."]}],"island_faqs":[{"question":"How do I get to Kaashidhoo Island?","answer":"Kaashidhoo Island can be reached by public ferry or speedboat from Male. Many accommodations can arrange transfers for guests."},{"question":"What is the best time to visit Kaashidhoo?","answer":"The best time to visit Kaashidhoo is during the dry season from November to April when the weather is sunny and rainfall is minimal. However, the island offers pleasant conditions year-round, with the wet season (May-October) bringing occasional rain showers but also fewer visitors and lower prices."},{"question":"What accommodation options are available on Kaashidhoo?","answer":"Kaashidhoo offers various budget-friendly accommodations including family-run guesthouses and beachfront properties. Most accommodations offer air conditioning, private bathrooms, meal packages, and can arrange tours and transfers."},{"question":"What activities are available on Kaashidhoo?","answer":"Kaashidhoo offers excellent snorkeling right from the beach, scuba diving excursions, sandbank visits, cultural experiences, and opportunities to participate in traditional fishing. The island''s peaceful atmosphere is perfect for relaxation and enjoying the natural beauty of the Maldives."}],"island_nearby_slugs":["himmafushi","huraa","dhiffushi","maafushi","gulhi","guraidhoo","hulhumale","male","gaafaru"]}'::jsonb
where node_type = 'location' and slug = 'kaashidhoo';


