update nodes set attributes = coalesce(attributes, '{}'::jsonb) || '{"island_content_source":"legacy_mtg_guide","island_quick_facts":[],"island_overview":[],"island_sections":[],"island_faqs":[{"question":"How do I get to Kudarikilu Island?","answer":"Public ferry service operates weekly from Male (approximately 10 hours journey time)."},{"question":"What is the best time to visit Kudarikilu Island?","answer":"The best time to visit Kudarikilu Island is during the northeast monsoon season (December to April), which brings dry, sunny weather with lower humidity and calmer seas."}],"island_nearby_slugs":[]}'::jsonb
